diff --git a/tests/integration/utils/neon-test-db.ts b/tests/integration/utils/neon-test-db.ts
index 46de128..edff07e 100644
--- a/tests/integration/utils/neon-test-db.ts
+++ b/tests/integration/utils/neon-test-db.ts
@@ -6,9 +6,39 @@
  * Each Vitest worker gets its own isolated branch.
  */

-import { createApiClient, EndpointType } from '@neondatabase/api-client';
 import { execFileSync } from 'child_process';

+import { createApiClient, EndpointType } from '@neondatabase/api-client';
+
+/**
+ * Retry wrapper with exponential backoff for transient Neon API failures.
+ */
+async function withRetry<T>(
+  fn: () => Promise<T>,
+  label: string,
+  maxAttempts = 3,
+  baseDelayMs = 2000
+): Promise<T> {
+  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
+    try {
+      return await fn();
+    } catch (error) {
+      if (attempt === maxAttempts) {
+        console.error(`${label} failed after ${maxAttempts} attempts`);
+        throw error;
+      }
+      const delay = baseDelayMs * Math.pow(2, attempt - 1);
+      console.warn(
+        `${label} failed (attempt ${attempt}/${maxAttempts}), retrying in ${delay}ms...`,
+        error instanceof Error ? error.message : error
+      );
+      await new Promise((resolve) => setTimeout(resolve, delay));
+    }
+  }
+  // Unreachable, but satisfies TypeScript
+  throw new Error(`${label} failed`);
+}
+
 const NEON_API_KEY = process.env.NEON_API_KEY;
 const NEON_PROJECT_ID =
   process.env.NEON_PROJECT_ID || 'withered-shape-05694257';
@@ -94,18 +124,22 @@ export async function createTestBranch(): Promise<TestBranchInfo> {
   try {
     const client = getApiClient();

-    // Create the branch with a read-write endpoint
-    const response = await client.createProjectBranch(NEON_PROJECT_ID, {
-      branch: {
-        name: branchName
-        // Branches from main by default
-      },
-      endpoints: [
-        {
-          type: EndpointType.ReadWrite
-        }
-      ]
-    });
+    // Create the branch with a read-write endpoint (with retry for transient failures)
+    const response = await withRetry(
+      () =>
+        client.createProjectBranch(NEON_PROJECT_ID, {
+          branch: {
+            name: branchName
+            // Branches from main by default
+          },
+          endpoints: [
+            {
+              type: EndpointType.ReadWrite
+            }
+          ]
+        }),
+      'createProjectBranch'
+    );

     const branch = response.data.branch;
     const endpoints = response.data.endpoints;
@@ -114,13 +148,20 @@ export async function createTestBranch(): Promise<TestBranchInfo> {
       throw new Error('Branch created but no endpoint returned');
     }

-    // Get the connection string for the new branch
-    const connectionResponse = await client.getConnectionUri({
-      projectId: NEON_PROJECT_ID,
-      branch_id: branch.id,
-      role_name: 'neondb_owner',
-      database_name: 'neondb'
-    });
+    // Wait for the branch endpoint to become active before proceeding
+    await waitForBranchReady(branch.id, 60000);
+
+    // Get the connection string for the new branch (with retry for transient failures)
+    const connectionResponse = await withRetry(
+      () =>
+        client.getConnectionUri({
+          projectId: NEON_PROJECT_ID,
+          branch_id: branch.id,
+          role_name: 'neondb_owner',
+          database_name: 'neondb'
+        }),
+      'getConnectionUri'
+    );

     const connectionString = connectionResponse.data.uri;

@@ -211,7 +252,7 @@ export async function deleteTestBranch(): Promise<void> {
  */
 export async function waitForBranchReady(
   branchId: string,
-  timeoutMs = 30000
+  timeoutMs = 60000
 ): Promise<void> {
   const startTime = Date.now();

